import {meta,courses,terms,categories,categoryTargets,sources,courseColors,readingWeek} from './data.js';
import {lessons} from './lessons.js';
import {freshState,validateState,loadState,storeState,escapeHTML as e,thaiDate,today,courseProgress,progress,nextLesson,exams,examClashes,planSummary,cardsForReview,reviewCard,quizItems,examICS} from './core.js';

const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5v16M3 4h5a4 4 0 0 1 4 3 4 4 0 0 1 4-3h5v15h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3z"/>',cards:'<rect x="7" y="3" width="13" height="16" rx="2"/><path d="M4 7H3v14h13v-1M11 8h5m-5 4h5"/>',plan:'<path d="M8 5h13M8 12h13M8 19h13m-19-15 1 1 2-2m-3 8 1 1 2-2m-3 8 1 1 2-2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',notes:'<path d="M14 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9M9 15l2-5 8-8 3 3-8 8z"/>',link:'<path d="M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=(name)=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('unavailable')},setItem(){throw Error('unavailable')}};}
const loaded=loadState(storage);let state=loaded.state;let locked=!!loaded.error;
let currentView='home',currentId='',reviewMode='cards',reviewCourse='',mistakesOnly=false,quizIndex=0,flipped=false,searchQuery='',reviewQueue=null;
const main=document.querySelector('#main');
const navItems=[['home','home','ห้องเรียนของฉัน'],['courses','book','บทเรียนทั้งหมด'],['review','cards','ทบทวนความจำ'],['plan','plan','แผนการเรียน'],['exams','calendar','ตารางสอบ'],['notes','notes','สมุดบันทึก']];
let toastTimer;
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function storageWarning(message){const el=document.querySelector('#storage-warning');el.hidden=!message;el.textContent=message||'';}
if(loaded.error)storageWarning(loaded.error);
function save(){if(locked){storageWarning('ยังบันทึกไม่ได้ เพราะข้อมูลเดิมอ่านไม่สำเร็จ ไปที่ตั้งค่าเพื่อนำเข้าไฟล์สำรอง หรือส่งออกงานในรอบนี้ก่อน');return false;}const ok=storeState(storage,state);if(!ok)storageWarning('บันทึกลงเครื่องไม่สำเร็จ พื้นที่อาจเต็มหรือเบราว์เซอร์ปิดกั้น กรุณาส่งออกข้อมูลก่อนปิดหน้า');else storageWarning('');return ok;}
const link=(hash,text,cls='button primary')=>`<a class="${cls}" href="#${hash}">${text}</a>`;
const badge=(txt,cls='')=>`<span class="badge ${cls}">${e(txt)}</span>`;
const courseById=id=>courses.find(c=>c.id===id);
const lessonById=id=>lessons.find(l=>l.id===id);
function heading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`;}
function smallProgress(p){return `<div class="progress-label"><span>เรียนแล้ว ${p.done} / ${p.total} บท</span><b>${p.percent}%</b></div><div class="progress-track" role="progressbar" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100" aria-label="ความคืบหน้าบทเรียน"><span style="width:${p.percent}%"></span></div>`;}
function color(c){return courseColors[courses.findIndex(v=>v.id===c.id)%courseColors.length];}
function card(c){const p=courseProgress(state,c.id);return `<a class="course-card" href="#course/${c.id}" style="--course:${color(c)}"><div class="course-top"><span class="course-icon">${icon('book')}</span><span class="code">${c.id}</span><span class="course-chevron">↗</span></div><h3>${e(c.title)}</h3><p>${e(c.reason)}</p><div class="course-meta">${badge(categories[c.category])}<span>5 บทเรียนพื้นฐาน</span></div>${smallProgress(p)}<div class="course-bottom"><span>${icon('calendar')} ${thaiDate(c.exam,true)} · ${c.slot}</span><span>เริ่มเรียน →</span></div></a>`;}
function home(){
 const p=progress(state);const next=(state.lastLesson&&!state.completed.includes(state.lastLesson)?lessonById(state.lastLesson):null)||nextLesson(state);const c=courseById(next.course);const due=cardsForReview(state).length;
 const todayCount=new Set(state.sessions.filter(s=>s.date===today()).map(s=>s.lesson)).size;
 return `${heading('MY LEARNING SPACE','วันนี้ มาเรียนกันต่อ','ค่อย ๆ เข้าใจพื้นฐาน แล้วต่อยอดไปทีละบท',`<span class="date-label">${thaiDate(today())}</span>`)}
 <section class="hero"><div class="hero-content"><span class="hero-tag">${state.lastLesson?'เรียนต่อจากที่ค้างไว้':'เริ่มต้นเส้นทางการเรียน'}</span><div class="hero-code">${next.course} · บทที่ ${next.n}</div><h2>${e(next.title)}</h2><p>${e(c.title)}<br>อ่านแนวคิด ดูตัวอย่าง แล้วลองทบทวนด้วยตัวเอง</p>${link('lesson/'+next.id,`${state.lastLesson?'เรียนต่อ':'เริ่มบทแรก'} ${icon('arrow')}`,'button white')}<span class="hero-time">${icon('clock')} ประมาณ ${next.minutes} นาที รวมทบทวน</span></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-paper"><span class="paper-label">POLITICAL SCIENCE</span><div class="paper-symbol">ร.บ.</div><i></i><i></i><i class="short"></i><div class="paper-bottom">เข้าใจ · เชื่อมโยง · ทบทวน</div></div><div class="art-book b1"></div><div class="art-book b2"></div><div class="art-spark">✦</div><div class="art-mini">หนึ่งบทใกล้เป้าหมายขึ้นอีกนิด</div></div></section>
 <div class="stats-grid"><div class="stat"><span class="stat-icon blue">${icon('book')}</span><div><b>${p.done}<small> / ${p.total}</small></b><span>บทเรียนที่อ่านจบ</span></div><div class="mini-ring" style="--p:${p.percent}%">${p.percent}%</div></div><a href="#review" class="stat"><span class="stat-icon mint">${icon('cards')}</span><div><b>${due}<small> ใบ</small></b><span>แฟลชการ์ดพร้อมทบทวน</span></div><span>↗</span></a><div class="stat"><span class="stat-icon sand">${icon('check')}</span><div><b>${todayCount}<small> / ${state.dailyGoal} บท</small></b><span>เป้าหมายวันนี้</span></div><span class="gentle">${todayCount>=state.dailyGoal?'ครบแล้ว ✓':'เริ่มได้เสมอ'}</span></div></div>
 <div class="section-heading"><div><h2>วิชาที่ลงเรียนเทอมนี้</h2><p>7 วิชา · 21 หน่วยกิต · ใช้รายการลงทะเบียนจริงของคุณ</p></div>${link('courses','ดูบทเรียนทั้งหมด →','text-link')}</div>
 <div class="course-grid">${courses.filter(c=>c.enrolled).map(card).join('')}</div>
 <section class="reading-rhythm"><div><span class="eyebrow">YOUR OWN PACE</span><h2>วิชาหนักสลับวิชาที่อ่านคล่อง</h2><p>เริ่มจาก POL1101 และ POL2301 แล้วสลับปรัชญา / เปรียบเทียบกับพรรคการเมือง / HR ไม่ต้องอ่านหนักทุกวัน</p></div>${link('plan','ดูจังหวะอ่านรายสัปดาห์','button secondary')}</section>
 <p class="quiet-note">${meta.scope} · แบบทบทวนเป็นโจทย์แต่งใหม่ รูปแบบข้อสอบจริงต้องดูประกาศผู้สอน</p>`;
}
function courseLibrary(){return `${heading('COURSE LIBRARY','บทเรียนทั้งหมด','35 บทเรียนพื้นฐาน อ่านต่อได้จากทุกวิชาในเทอมนี้')}<label class="searchbox">${icon('search')}<input id="lesson-search" type="search" placeholder="ค้นหารหัสวิชา หัวข้อ หรือแนวคิด เช่น ความชอบธรรม" value="${e(searchQuery)}" aria-label="ค้นหาบทเรียน"></label><div id="library-results">${libraryResults()}</div>`;}
function libraryResults(){if(!searchQuery.trim())return `<div class="course-grid">${courses.filter(c=>c.enrolled).map(card).join('')}</div>`;const q=searchQuery.toLocaleLowerCase();const found=lessons.filter(l=>(l.course+l.title+l.intro+l.sections.map(s=>s.body).join(' ')).toLocaleLowerCase().includes(q));return `<p class="result-count">พบ ${found.length} บทเรียน</p><div class="lesson-list">${found.map(lessonRow).join('')||'<div class="empty">ยังไม่พบหัวข้อนี้ ลองใช้คำสั้นลงหรือค้นด้วยรหัสวิชา</div>'}</div>`;}
function lessonRow(l){const done=state.completed.includes(l.id);return `<a class="lesson-row ${done?'done':''}" href="#lesson/${l.id}"><span class="lesson-number">${done?icon('check'):String(l.n).padStart(2,'0')}</span><div><span class="code muted">${l.course}</span><h3>${e(l.title)}</h3><p>${e(l.intro)}</p></div><span class="lesson-duration">${l.minutes} นาที<br><b>${done?'อ่านจบแล้ว':'เริ่มอ่าน →'}</b></span></a>`;}
function coursePage(id){const c=courseById(id);if(!c||!c.enrolled)return missing();const ls=lessons.filter(l=>l.course===id),p=courseProgress(state,id);return `${link('courses','← กลับไปทุกวิชา','back-link')}${heading(c.id,e(c.title),e(c.reason),badge('ลงทะเบียนแล้ว','green'))}<div class="course-overview"><div>${smallProgress(p)}</div><span>${icon('calendar')} ${thaiDate(c.exam)} · คาบ ${c.slot}</span><span>${badge(categories[c.category])} 3 หน่วยกิต</span></div><div class="notice">บทเรียนในแอปเป็นชุดปูพื้นฐาน 5 บทของวิชานี้ ใช้คู่ตำราและคำบรรยายอาจารย์ ขอบเขตและรูปแบบสอบภาค 2/2569 ยังต้องตรวจประกาศผู้สอน</div><div class="lesson-list">${ls.map(lessonRow).join('')}</div><div class="resource-strip"><div><h3>เรียนคู่กับคำบรรยายมหาวิทยาลัย</h3><p>ค้นรหัส ${c.id} แล้วเลือกภาคเรียนให้ตรง หากใช้วิดีโอภาคเก่าให้ตรวจขอบเขตกับอาจารย์อีกครั้ง</p></div><a class="button secondary" href="https://ondemand.ru.ac.th/" target="_blank" rel="noopener noreferrer">เปิด RU on Demand ↗</a></div>`;}
function questionHTML(q,id,index,context='lesson'){const key=`${id}:${index}`,chosen=state.answers[key],answered=Number.isInteger(chosen);return `<div class="question-block"><div class="eyebrow">${context==='lesson'?`ทบทวน ${index+1}`:'ฝึกตอบทีละข้อ'}</div><h3>${e(q.prompt)}</h3><div class="choices">${q.options.map((o,i)=>`<button type="button" class="choice ${answered&&i===q.answer?'correct':''} ${answered&&i===chosen&&chosen!==q.answer?'incorrect':''}" data-action="answer" data-lesson="${id}" data-index="${index}" data-value="${i}" aria-pressed="${chosen===i}" ${answered?'disabled':''}><span>${'กขคง'[i]}</span>${e(o)}${answered&&i===q.answer?'<b>✓</b>':''}</button>`).join('')}</div>${answered?`<div class="answer-explanation ${chosen===q.answer?'correct':'incorrect'}"><strong>${chosen===q.answer?'ถูกต้อง':'ลองทบทวนแนวคิดอีกนิด'}</strong><p>${e(q.explanation)}</p></div>`:''}</div>`;}
function lessonPage(id){const l=lessonById(id);if(!l)return missing();state.lastLesson=id;save();const ls=lessons.filter(v=>v.course===l.course),next=ls.find(v=>v.n===l.n+1),done=state.completed.includes(id);return `${link('course/'+l.course,'← '+l.course+' · ดูทุกบท','back-link')}
 <div class="reader-top"><span>${badge(`บทที่ ${l.n} / 5`)} <span class="muted">บทเรียนพื้นฐาน · ${l.minutes} นาที</span></span><button class="button subtle small" data-action="font">${state.font==='large'?'ลด':'เพิ่ม'}ขนาดตัวอักษร</button></div>
 <div class="reader-layout"><article class="reading-article"><h1>${e(l.title)}</h1><p class="lesson-intro">${e(l.intro)}</p><div class="reading-divider"></div>${l.sections.map((s,i)=>`<section id="section-${i}" class="reading-section"><span class="section-num">0${i+1}</span><h2>${e(s.heading)}</h2><p>${e(s.body)}</p></section>`).join('')}
 <section class="worked-example"><div class="eyebrow">ลองใช้แนวคิด</div><h2>จากสถานการณ์สู่การวิเคราะห์</h2><p>${e(l.example.situation)}</p><div class="analysis-box"><strong>วิธีมองเรื่องนี้</strong><p>${e(l.example.analysis)}</p></div></section><div class="trap"><strong>จุดที่มักสับสน</strong><p>${e(l.trap)}</p></div>
 <section class="recap"><h2>คำสำคัญที่ควรอธิบายได้</h2>${l.cards.map(c=>`<div><b>${e(c.front)}</b><p>${e(c.back)}</p></div>`).join('')}</section>
 <section class="lesson-quiz"><div class="section-heading"><div><h2>ลองตอบโดยไม่เปิดย้อน</h2><p>โจทย์แต่งใหม่เพื่อเช็กความเข้าใจ</p></div><button class="text-button" data-action="retry" data-id="${id}">ลองใหม่</button></div>${l.questions.map((q,i)=>questionHTML(q,id,i)).join('')}</section>
 <div class="reflection"><strong>อธิบายให้ตัวเองฟัง</strong><p>${e(l.reflection)}</p></div>
 <div class="lesson-finish"><button class="button ${done?'secondary':'primary'}" data-action="complete" data-id="${id}">${icon('check')} ${done?'อ่านจบแล้ว · ยกเลิกเครื่องหมาย':'ทำเครื่องหมายว่าอ่านจบ'}</button>${next?link('lesson/'+next.id,'บทถัดไป →','button secondary'):link('review','ทบทวนด้วยแฟลชการ์ด →','button secondary')}</div><p class="quiet-note">เรียบเรียงใหม่ 10 ต.ค. 2569 · ไม่ใช่คำบรรยายของอาจารย์หรือขอบเขตข้อสอบทางการ · <a href="#about">แหล่งเรียนรู้</a></p></article>
 <aside class="reading-side"><div class="sticky-side"><div class="panel"><span class="eyebrow">ในบทนี้</span><ol class="toc">${l.sections.map((s,i)=>`<li><button data-action="section" data-index="${i}">${e(s.heading)}</button></li>`).join('')}</ol></div><div class="panel note-panel"><h3>${icon('notes')} บันทึกของฉัน</h3><p>เขียนสิ่งที่เข้าใจ หรือคำถามที่จะกลับมาค้น</p><label class="sr-only" for="lesson-note">บันทึกบท ${e(l.title)}</label><textarea id="lesson-note" data-lesson="${id}" maxlength="50000" placeholder="ลองสรุปด้วยภาษาของตัวเอง…">${e(state.notes[id]||'')}</textarea><span id="note-status" class="save-status" role="status">บันทึกในเบราว์เซอร์นี้อัตโนมัติ</span></div><div class="next-lessons"><span class="eyebrow">บทอื่นในวิชานี้</span>${ls.filter(v=>v.id!==id).map(v=>`<a href="#lesson/${v.id}">${v.n}. ${e(v.title)} <span>${state.completed.includes(v.id)?'✓':'→'}</span></a>`).join('')}</div></div></aside></div>`;}
function review(){const due=cardsForReview(state,reviewCourse);if(reviewQueue===null)reviewQueue=quizItems(state,reviewCourse,mistakesOnly);const qs=reviewQueue;return `${heading('RETRIEVAL PRACTICE','ทบทวนความจำ','นึกคำตอบก่อนเปิดเฉลย แล้วกลับมาทบทวนสิ่งที่ยังไม่แม่น')}<div class="review-toolbar"><div class="segmented"><button data-action="mode" data-mode="cards" class="${reviewMode==='cards'?'active':''}">แฟลชการ์ด</button><button data-action="mode" data-mode="quiz" class="${reviewMode==='quiz'?'active':''}">คำถามทบทวน</button></div><label class="select-wrap">วิชา<select id="review-course"><option value="">ทุกวิชา</option>${courses.filter(c=>c.enrolled).map(c=>`<option value="${c.id}" ${reviewCourse===c.id?'selected':''}>${c.id}</option>`).join('')}</select></label></div>${reviewMode==='cards'?flashcardHTML(due):quizHTML(qs)}<p class="quiet-note">การทบทวนไม่ใช่ผลสอบมหาวิทยาลัย · คะแนนในแอปใช้ดูความเข้าใจเท่านั้น</p>`;}
function flashcardHTML(due){if(!due.length)return `<div class="empty panel"><span class="empty-symbol">✓</span><h2>ทบทวนครบสำหรับวันนี้แล้ว</h2><p>บัตรที่ตอบแล้วจะกลับมาตามรอบ 1, 3 หรือ 7 วัน</p>${link('courses','กลับไปเรียนบทอื่น')}</div>`;const c=due[0];return `<div class="review-counter">พร้อมทบทวน ${due.length} ใบ <span>ตอบแล้วจะนัดทบทวนให้ในรอบถัดไป</span></div><div class="flashcard ${flipped?'flipped':''}"><span class="code">${c.course}</span><span class="eyebrow">${flipped?'คำอธิบาย':'ลองนึกความหมาย'}</span><h2>${e(flipped?c.back:c.front)}</h2><p>${e(c.title)}</p><button class="button ${flipped?'secondary':'primary'}" data-action="flip">${flipped?'กลับไปดูคำถาม':'เปิดคำอธิบาย'}</button></div>${flipped?`<div class="review-actions"><button class="button secondary" data-action="remember" data-id="${c.id}" data-value="no">ยังไม่แม่น · พรุ่งนี้</button><button class="button primary" data-action="remember" data-id="${c.id}" data-value="yes">จำได้แล้ว ${icon('check')}</button></div>`:'<p class="center muted">ลองตอบออกเสียงสั้น ๆ ก่อนเปิดการ์ด</p>'}${link('lesson/'+c.lesson,'กลับไปอ่านบทนี้ →','center text-link')}`;}
function quizHTML(qs){if(quizIndex>=qs.length)quizIndex=0;const q=qs[quizIndex];return `<label class="check-label"><input type="checkbox" id="mistakes-only" ${mistakesOnly?'checked':''}> เฉพาะข้อที่เคยตอบผิด</label>${!q?`<div class="empty panel"><h2>${mistakesOnly?'ยังไม่มีข้อที่ตอบผิด':'ยังไม่มีคำถาม'}</h2><p>เปลี่ยนตัวกรองเพื่อฝึกข้ออื่นได้</p></div>`:`<div class="quiz-shell panel"><div class="review-counter">ข้อ ${quizIndex+1} / ${qs.length} <span>${q.course} · ${e(q.title)}</span></div>${questionHTML(q,q.lesson,q.index,'review')}<div class="review-actions"><button class="button secondary" data-action="quiz-prev" ${quizIndex===0?'disabled':''}>← ก่อนหน้า</button><a href="#lesson/${q.lesson}" class="text-link">อ่านบทที่เกี่ยวข้อง</a><button class="button primary" data-action="quiz-next">${quizIndex+1===qs.length?'กลับไปข้อแรก':'ข้อถัดไป →'}</button></div><button class="text-button" data-action="retry-one" data-id="${q.id}">ตอบข้อนี้ใหม่</button></div>`}`;}
function plan(){const s=planSummary(state);return `${heading('LEARNING ROADMAP','แผนการเรียนของฉัน','ฐานแผน C · เรียนให้ได้วุฒิก่อน · ภาระหนักสลับเบากว่า')}<div class="plan-banner"><div><span class="eyebrow">เป้าหมายตามแผน</span><h2>สอบครบภายใน 1/2571</h2><p>ประมาณ 2 ปีจากภาค 2/2569 · 6 ภาค รวมฤดูร้อน · สำรองถึง 2/2571</p></div><b>84 <small>หน่วยกิตในแผน</small></b></div><div class="notice">แผนนี้คาดว่าเทียบโอนได้ 42 หน่วยกิต แต่ยังไม่ถือว่าอนุมัติแล้ว ทุกภาคถัดไปต้องปรับตามวิชาเปิด คาบสอบ และผลสอบจริง ระดับหนัก/กลาง/เบากว่าเป็นการประเมินเพื่อกระจายภาระ ไม่ใช่สถิติความง่าย</div>
 <div class="section-heading"><h2>โครงสร้างวิชาที่ต้องเก็บ</h2><span class="muted">ไม่ซ้ำหมวด · 28 วิชา</span></div><div class="category-grid">${Object.entries(categoryTargets).map(([cat,target])=>`<div class="panel"><span>${categories[cat]}</span><b>${s.planned[cat]} <small>/ ${target} นก.</small></b><span class="green-text">วางแผนครบ ✓</span><small>สอบผ่านที่บันทึก ${s.passed[cat]} นก.</small></div>`).join('')}</div>
 <div class="section-heading"><h2>รายวิชาแต่ละภาค</h2><span class="muted">ย้ายวิชาอนาคตได้ตามวิชาเปิด</span></div>${s.termRows.map(t=>`<section class="term-panel panel ${t.over?'over':''}"><div class="term-title"><div><span class="term-number">${t.id===6?'เผื่อ':String(t.id+1).padStart(2,'0')}</span><div><h3>${t.name}</h3><span>${t.label} ${t.id===0?'· รายการจริง':'· แผนปรับได้'}</span></div></div><div><b>${t.credits} นก.</b><span>หนัก ${t.heavy} / กลาง ${t.courses.filter(c=>c.load==='กลาง').length} / เบากว่า ${t.courses.filter(c=>c.load==='เบากว่า').length}</span></div></div>${t.over?`<div class="notice danger">เกินเพดานวางแผน ${t.cap} หน่วยกิต ต้องลดหรือขอสิทธิตามระเบียบก่อนลงจริง</div>`:''}${t.heavy>2?'<div class="notice">วิชาที่ประเมินว่าหนักเกิน 2 วิชาในภาคนี้ ลองกระจายภาระอีกครั้ง</div>':''}${t.courses.length?`<div class="table-scroll"><table><thead><tr><th>วิชา</th><th>หมวด / ภาระ</th><th>วันสอบ</th><th>ผลสอบที่บันทึกเอง</th>${t.id?' <th>ย้ายไปภาค</th>':''}</tr></thead><tbody>${t.courses.map(c=>`<tr><td><b>${c.id}</b><div>${e(c.title)}</div><small>${e(c.reason)}</small></td><td>${e(categories[c.category])}<br>${badge(c.load,c.load==='หนัก'?'amber':'')}</td><td>${c.exam?`${thaiDate(c.exam,true)}<br>คาบ ${c.slot}`:'รอประกาศ'}</td><td><select class="grade-select" data-course="${c.id}" aria-label="ผลสอบ ${c.id}"><option value="">${c.enrolled?'ลงแล้ว / รอสอบ':'ยังไม่บันทึก'}</option>${['A','B+','B','C+','C','D+','D','F'].map(g=>`<option ${state.grades[c.id]===g?'selected':''}>${g}</option>`).join('')}</select></td>${t.id?`<td><select class="move-select" data-course="${c.id}" aria-label="ย้าย ${c.id}">${terms.filter(v=>v.id>0).map(v=>`<option value="${v.id}" ${v.id===t.id?'selected':''}>${v.name}</option>`).join('')}</select></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<p class="muted">ยังไม่มีวิชา ใช้เผื่อวิชาที่ต้องเลื่อนหรือสอบใหม่</p>'}</section>`).join('')}
 <div class="split-grid"><section class="panel"><h2>ติดตามผลที่ยืนยันแล้ว</h2><p>กรอกเฉพาะหน่วยกิตที่มหาวิทยาลัยอนุมัติ</p><label class="field">ศึกษาทั่วไปที่อนุมัติ (0–30)<input id="transfer-general" type="number" min="0" max="30" step="1" value="${state.transfer.general}"></label><label class="field">เลือกเสรีที่อนุมัติ (0–12)<input id="transfer-free" type="number" min="0" max="12" step="1" value="${state.transfer.free}"></label><button class="button secondary" data-action="save-transfer">บันทึกผลเทียบโอน</button><div class="metrics-line">เทียบโอนยืนยัน <b>${s.transfer}</b> · สอบผ่าน <b>${s.earned}</b> · ยังไม่ยืนยันครบหลักสูตร <b>${s.remaining}</b> นก.</div><p>GPA จำลองจากเกรดที่บันทึก: <b>${s.gpa===null?'ยังไม่มีข้อมูล':s.gpa.toFixed(2)}</b></p><small>ไม่รวมเทียบโอน; ไม่จำลองกฎสอบซ้ำหรือแทนเกรด ใช้ผลทางการตัดสินจบ และต้องครบหมวด + GPA ตามเกณฑ์</small></section><section class="panel"><h2>เมื่อเรียนแล้วไม่ไหว</h2><ul class="simple-list"><li>ประเมินหลังเรียน 3–4 สัปดาห์: อ่านทันหรือไม่ และอธิบายพื้นฐานได้แค่ไหน</li><li>ลดงานอ่านเสริมก่อน แล้วกระจายวิชาหนักในภาคถัดไป</li><li>หากวิชาไม่เปิดหรือสอบชน ให้สลับวิชาในหมวดเดิม พร้อมตรวจหน่วยกิตไม่ซ้ำ</li><li>วิชาเทอมแรกลงแล้ว การเพิ่ม–ถอนต้องทำตามปฏิทินมหาวิทยาลัย</li><li>การอ่านเตรียมสอบปลัดเป็นกิจกรรมเสริมตามสมัครใจ เป้าหมายตอนนี้คือเรียนและสอบผ่าน</li></ul></section></div>
 <div class="section-heading"><h2>จังหวะอ่านหนึ่งสัปดาห์</h2><span class="muted">ปรับได้ตามพลังและเวลาจริง</span></div><div class="week-grid">${readingWeek.map(([day,primary,text,secondary])=>`<div class="panel"><span class="eyebrow">${day}</span><b>${primary}</b><p>${text}</p><small>สลับ ${secondary} 20–30 นาที เมื่อมีเวลา</small></div>`).join('')}</div><p class="quiet-note">ลำดับในแผนเป็นคำแนะนำในการปูพื้นฐาน ไม่ใช่การยืนยันวิชาบังคับก่อนตามทะเบียน · ยังไม่ยืนยันรูปแบบข้อสอบของแต่ละวิชา</p>`;}
function examPage(){const items=exams();const clashes=examClashes(items);return `${heading('EXAM CALENDAR','ตารางสอบเทอมนี้','ภาค 2/2569 · วันที่ตามรายการลงทะเบียนที่คุณส่ง',`<button class="button secondary" data-action="calendar">${icon('download')} เพิ่มลงปฏิทิน</button>`)}<div class="exam-summary"><span class="stat-icon mint">${icon('check')}</span><div><b>${clashes.length?'พบคาบสอบซ้ำ':'7 วิชา · วันและคาบไม่ชนกันในรายการนี้'}</b><p>สอบระหว่าง 10–22 มีนาคม 2570 · A/B เป็นรหัสคาบ ให้ตรวจชั่วโมงสอบและห้องสอบจากตารางรายบุคคล</p></div></div><div class="exam-timeline">${items.map(c=>`<article class="exam-item"><div class="exam-date"><b>${Number(c.exam.slice(8))}</b><span>มี.ค. 2570</span></div><div><span class="code">${c.id}</span><h3>${e(c.title)}</h3><span class="muted">3 หน่วยกิต · รูปแบบข้อสอบรอยืนยันผู้สอน</span></div><span class="slot">คาบ ${c.slot}</span>${link('course/'+c.id,'เปิดบทเรียน →','button secondary small')}</article>`).join('')}</div><div class="notice">ไฟล์ปฏิทินบันทึกเป็นกิจกรรมทั้งวัน พร้อมรหัสคาบ เพื่อไม่ใส่เวลาเอง ก่อนสอบตรวจประกาศแก้ไข ตารางสอบรายบุคคล สถานที่ และอุปกรณ์ที่อนุญาตอีกครั้ง</div><div class="panel"><h3>แผนทบทวนก่อนสอบ</h3><p>ก่อนสอบ 4 สัปดาห์ ให้เน้นบทที่ยังอธิบายเองไม่ได้และคำถามที่ตอบผิด แบ่งอ่านตามลำดับวันสอบจริง โดยกันเวลาต่อเนื่องให้ POL2106 และ POL2107 ไม่รออ่านในคืนก่อนสอบ</p><p>วันที่ 21 และ 22 มีนาคมสอบติดกัน จัดสรุป POL2301 และ POL2107 ให้พร้อมก่อนเริ่มช่วงสอบ</p></div>`;}
function notes(){const saved=lessons.filter(l=>(state.notes[l.id]||'').trim());return `${heading('PERSONAL NOTEBOOK','สมุดบันทึกของฉัน','สรุปด้วยคำของตัวเอง แล้วกลับมาเติมจากคำบรรยายอาจารย์',`<button class="button secondary" data-action="export-notes">${icon('download')} ดาวน์โหลดบันทึก</button>`)}${saved.length?`<div class="notes-grid">${saved.map(l=>`<article class="panel saved-note"><span class="code">${l.course}</span><h2>${e(l.title)}</h2><p class="note-preview">${e(state.notes[l.id])}</p>${link('lesson/'+l.id,'อ่านและแก้บันทึก →','text-link')}</article>`).join('')}</div>`:`<div class="empty panel"><span class="empty-symbol">${icon('notes')}</span><h2>พื้นที่สำหรับความเข้าใจของคุณ</h2><p>เปิดบทเรียนแล้วเขียนบันทึกในช่อง “บันทึกของฉัน” ข้อความจะรวมอยู่ที่นี่</p>${link('courses','เลือกบทเรียน')}</div>`}`;}
function about(){return `${heading('SOURCES & CONTEXT','แหล่งเรียนรู้และข้อตกลงของแผน','ข้อมูลที่ใช้สร้างห้องเรียนนี้ · อัปเดต 10 ตุลาคม 2569')}<div class="panel source-intro"><h2>อ่านบทพื้นฐาน แล้วเรียนต่อกับอาจารย์</h2><p>${meta.scope} เนื้อหาแนวคิดและตัวอย่างในแอปเป็นงานเรียบเรียงใหม่ ไม่ได้คัดลอกตำราหรือถอดคำบรรยายมหาวิทยาลัย คำถามเป็นแบบฝึกของแอป ไม่ใช่ข้อสอบจริง</p><p>ยังไม่ได้ตรวจความครอบคลุมกับแผนการสอนของผู้สอนภาค 2/2569 ทุกคน ให้นำหัวข้อที่อาจารย์ประกาศมาเทียบและเพิ่มบันทึกหลังเรียน โดยเฉพาะกฎหมาย กติกาสถาบัน และเหตุการณ์ร่วมสมัยที่เปลี่ยนได้</p></div><div class="source-grid">${sources.map(s=>`<article class="panel"><span class="source-icon">${icon(s.url?'link':'notes')}</span><h3>${e(s.title)}</h3><p>${e(s.detail)}</p>${s.url?`<a class="text-link" href="${s.url}" target="_blank" rel="noopener noreferrer">เปิดแหล่งข้อมูล ↗</a>`:badge('หลักฐานจากผู้เรียน','green')}</article>`).join('')}</div><section class="panel context"><h2>สิ่งที่ตกลงไว้สำหรับแผนนี้</h2><ul class="simple-list"><li>เรียนปริญญาตรีใบที่สอง ใช้สิทธิเทียบโอนวุฒิจากสถาบันอื่น ฐานแผน C บริหารรัฐกิจ ส่วนกลาง</li><li>ให้การเรียนจบเร็วและสอบผ่านเป็นเป้าหมายหลัก ไม่เลือกวิชาเพื่อนำไปประยุกต์กับงานเดิม</li><li>เป้าหมายเดิมเรื่องสอบปลัดยังเป็นบริบทระยะยาว แต่แผนนี้ไม่บังคับอ่านติวเพิ่ม และไม่คาดเดาวันเปิดสอบรอบหน้า</li><li>เทอมแรกใช้ 7 วิชาที่ลงจริงตามภาพ ไม่ใช้รายการตัวอย่างหรือรายการในแผน Excel เก่าแทน</li><li>POL2104 นับเป็นวิชาเลือกในคณะของแผน C ส่วน POL2301 และ POL2303 เป็นเอกบังคับ C</li><li>การลงข้ามกลุ่มวิชาไม่ได้ทำให้ยืนยันขั้นตอนประกาศแผนกับคณะได้ อาศัยโครงสร้างที่เรียนครบและข้อมูลทะเบียนของมหาวิทยาลัย</li><li>คาดเทียบโอน 42 นก. และวางแผนเรียน 84 นก. ผลอนุมัติรายบุคคลและการสำเร็จการศึกษาต้องใช้หลักฐานทางการ</li></ul><details><summary>ข้อมูลค่าใช้จ่ายที่เคยคุยกัน</summary><p>ภาพใบสมัครแสดงยอด 3,825 บาท และรายการเทียบโอนจากสถาบันอื่น 100 บาท ยอดในภาพไม่ใช่หลักฐานว่าจ่ายแล้ว ผลเทียบโอนและยอดคงเหลือต้องตรวจมหาวิทยาลัย ไม่แสดงว่าระบบจะคำนวณอัตโนมัติแน่นอน</p><p>ตามฐานประมาณ 42 นก. × 100 บาท = 4,200 บาท หาก 100 บาทแรกชำระและนับหักได้ จะคงเหลือประมาณ 4,100 บาท ทั้งนี้ขึ้นกับจำนวนอนุมัติจริงและการแจ้งยอดของคณะ</p></details></section>`;}
function settings(){return `${heading('YOUR STUDY DATA','ตั้งค่าและสำรองข้อมูล','ความคืบหน้า คำตอบ แฟลชการ์ด และบันทึกของคุณ')}<div class="split-grid"><section class="panel"><h2>จังหวะการเรียน</h2><label class="field">เป้าหมายอ่านจบต่อวัน<select id="daily-goal">${[1,2,3].map(n=>`<option value="${n}" ${state.dailyGoal===n?'selected':''}>${n} บท</option>`).join('')}</select></label><label class="field">ขนาดตัวอักษรบทเรียน<select id="font-choice"><option value="normal" ${state.font==='normal'?'selected':''}>ปกติ</option><option value="large" ${state.font==='large'?'selected':''}>ใหญ่</option></select></label><p class="muted">เป้าหมายใช้ช่วยจัดเวลา ไม่ต้องเร่งให้ครบเมื่อเหนื่อย</p></section><section class="panel"><h2>ย้ายเครื่องหรือเก็บสำรอง</h2><p>ข้อมูลบันทึกในเบราว์เซอร์นี้ ยังไม่ซิงก์ข้ามมือถือกับคอมพิวเตอร์ การล้างข้อมูลเบราว์เซอร์อาจทำให้ข้อมูลหาย</p><button class="button primary" data-action="export">${icon('download')} ส่งออกข้อมูลทั้งหมด (.json)</button><label class="import-label">นำเข้าไฟล์สำรอง<input type="file" id="import-backup" accept=".json,application/json"></label><p class="quiet-note">นำเข้าจะแทนที่ข้อมูลในเครื่องนี้หลังยืนยัน แนะนำส่งออกก่อนทุกครั้ง ไฟล์รองรับขนาดไม่เกิน 2 MB</p>${locked?'<button class="button secondary" data-action="recover-session">ใช้ข้อมูลของรอบนี้แทนข้อมูลเดิมที่อ่านไม่ได้</button>':''}</section></div><section class="panel"><h2>นำแผนไปใช้งาน</h2><p>ส่งออกแผนทุกภาคเป็น CSV สำหรับเปิดใน Excel และวันสอบเป็นปฏิทินได้</p><div class="button-row"><button class="button secondary" data-action="export-plan">ดาวน์โหลดแผน (.csv)</button><button class="button secondary" data-action="calendar">ดาวน์โหลดปฏิทิน (.ics)</button></div><p class="quiet-note">CSV เป็นตารางข้อมูล ไม่ใช่สมุดงาน Excel หลายชีต วันสอบอนาคตระบุ “รอประกาศ”</p></section>`;}
function missing(){return `<div class="empty panel"><h1>ไม่พบหน้าที่เลือก</h1><p>เลือกบทเรียนจากรายการอีกครั้งได้เลย</p>${link('courses','ไปที่บทเรียน')}</div>`;}
function updateNav(){document.querySelector('#navigation').innerHTML=navItems.map(([key,i,label])=>`<a class="nav-link ${((currentView==='lesson'||currentView==='course')?'courses':currentView)===key?'active':''}" href="#${key}" ${currentView===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='courses'?'<small>7</small>':''}</a>`).join('');document.querySelector('#breadcrumb').textContent=currentView==='lesson'?`${currentId.split('-')[0]} / บทเรียน`:(navItems.find(n=>n[0]===currentView)?.[2]||{course:'บทเรียนรายวิชา',about:'แหล่งเรียนรู้',settings:'ตั้งค่า'}[currentView]||'ห้องเรียน');}
function render(keepScroll=false){const oldY=window.scrollY;document.documentElement.dataset.font=state.font;updateNav();main.innerHTML=({home,courses:courseLibrary,course:()=>coursePage(currentId),lesson:()=>lessonPage(currentId),review,plan,exams:examPage,notes,about,settings}[currentView]||missing)();document.title=`${currentView==='lesson'?(lessonById(currentId)?.title||'บทเรียน'):(document.querySelector('#breadcrumb').textContent)} · RU Study Planner`;if(keepScroll)window.scrollTo(0,oldY);else window.scrollTo(0,0);}
function navigate(){const raw=location.hash.slice(1)||'home';const [view,id]=raw.split('/');currentView=view;currentId=id||'';reviewQueue=null;render();main.focus({preventScroll:true});}
function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAll(){download(`ru-study-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('ส่งออกไฟล์สำรองแล้ว');}
function exportPlan(){const rows=[['ภาค','รหัส','รายวิชา','หน่วยกิต','หมวด','ภาระประมาณ','วันสอบ','คาบ','ผลสอบที่บันทึกเอง','เหตุผลลำดับเรียน'],...planSummary(state).termRows.flatMap(t=>t.courses.map(c=>[t.name,c.id,c.title,3,categories[c.category],c.load,c.exam?thaiDate(c.exam):'รอประกาศ',c.slot||'',state.grades[c.id]||'',c.reason]))];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('ru-study-plan-all-terms.csv',csv,'text/csv;charset=utf-8');}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='font'){state.font=state.font==='large'?'normal':'large';save();render(true);}
 if(action==='section')document.getElementById(`section-${b.dataset.index}`)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(action==='answer'){const l=lessonById(b.dataset.lesson),i=Number(b.dataset.index),v=Number(b.dataset.value);if(!l||!l.questions[i]||v<0||v>=l.questions[i].options.length)return;state.answers[`${l.id}:${i}`]=v;save();if(reviewMode==='quiz'&&mistakesOnly&&currentView==='review'){toast(v===l.questions[i].answer?'ตอบถูกแล้ว นำออกจากข้อที่ต้องทบทวน':'บันทึกแล้ว ดูคำอธิบายเพื่อทบทวน');}render(true);}
 if(action==='retry'){for(const key of Object.keys(state.answers))if(key.startsWith(b.dataset.id+':'))delete state.answers[key];save();render(true);}
 if(action==='retry-one'){delete state.answers[b.dataset.id];save();render(true);}
 if(action==='complete'){const id=b.dataset.id;if(!lessonById(id))return;if(state.completed.includes(id)){state.completed=state.completed.filter(v=>v!==id);state.sessions=state.sessions.filter(v=>!(v.lesson===id&&v.date===today()));}else {state.completed.push(id);if(!state.sessions.some(v=>v.lesson===id&&v.date===today()))state.sessions.push({lesson:id,date:today()});}save();render(true);toast(state.completed.includes(id)?'บันทึกว่าอ่านจบแล้ว ✓':'ยกเลิกเครื่องหมายแล้ว');}
 if(action==='mode'){reviewMode=b.dataset.mode;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(action==='flip'){flipped=!flipped;render(true);}
 if(action==='remember'){reviewCard(state,b.dataset.id,b.dataset.value==='yes');save();flipped=false;render(true);}
 if(action==='quiz-next'){quizIndex++;render(true);}
 if(action==='quiz-prev'){quizIndex=Math.max(0,quizIndex-1);render(true);}
 if(action==='calendar'){download('ru-exams-2-2569.ics',examICS(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินแบบทั้งวันพร้อมรหัสคาบแล้ว');}
 if(action==='export')exportAll();
 if(action==='export-plan')exportPlan();
 if(action==='export-notes'){const text=lessons.filter(l=>state.notes[l.id]?.trim()).map(l=>`# ${l.course} — ${l.title}\n\n${state.notes[l.id]}`).join('\n\n---\n\n');download('ru-study-notes.md',text||'# ยังไม่มีบันทึก\n','text/markdown;charset=utf-8');}
 if(action==='save-transfer'){const general=Number(document.querySelector('#transfer-general').value),free=Number(document.querySelector('#transfer-free').value);if(!Number.isInteger(general)||general<0||general>30||!Number.isInteger(free)||free<0||free>12){toast('กรอกจำนวนเต็มตามช่วงที่ระบุ');return;}state.transfer={general,free};save();render(true);toast('บันทึกหน่วยกิตที่ยืนยันแล้ว');}
 if(action==='recover-session'&&confirm('ใช้ข้อมูลรอบนี้แทนข้อมูลเดิมที่อ่านไม่ได้? ควรส่งออกข้อมูลรอบนี้ก่อน')){locked=false;save();render(true);}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='lesson-search'){searchQuery=el.value;document.querySelector('#library-results').innerHTML=libraryResults();}if(el.id==='lesson-note'){state.notes[el.dataset.lesson]=el.value;const ok=save();document.querySelector('#note-status').textContent=ok?'บันทึกแล้ว ✓':'ยังบันทึกไม่ได้ — ส่งออกข้อมูลก่อนปิดหน้า';}});
document.addEventListener('change',async event=>{const el=event.target;
 if(el.id==='review-course'){reviewCourse=el.value;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(el.id==='mistakes-only'){mistakesOnly=el.checked;quizIndex=0;reviewQueue=null;render(true);}
 if(el.classList.contains('grade-select')){if(el.value)state.grades[el.dataset.course]=el.value;else delete state.grades[el.dataset.course];save();render(true);toast('บันทึกผลที่กรอกแล้ว');}
 if(el.classList.contains('move-select')){state.termMoves[el.dataset.course]=Number(el.value);save();render(true);toast('ปรับภาคเรียนแล้ว ตรวจเพดานและวิชาเปิดก่อนลงจริง');}
 if(el.id==='daily-goal'){state.dailyGoal=Number(el.value);save();toast('ปรับเป้าหมายแล้ว');}
 if(el.id==='font-choice'){state.font=el.value;save();render(true);}
 if(el.id==='import-backup'){const file=el.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('ไฟล์เกิน 2 MB');const candidate=validateState(JSON.parse(await file.text()));if(!confirm(`นำเข้าบทที่อ่านจบ ${candidate.completed.length} บท และบันทึก ${Object.keys(candidate.notes).length} รายการ เพื่อแทนที่ข้อมูลเครื่องนี้?`)){el.value='';return;}state=candidate;locked=false;save();render();toast('นำเข้าข้อมูลสำเร็จ');}catch(err){toast('นำเข้าไม่สำเร็จ: '+(err.message||'รูปแบบไฟล์ไม่ถูกต้อง'));el.value='';}}
});
window.addEventListener('hashchange',navigate);
navigate();
